// Classic BBS presentation: local reactions are separate from investigation progress.
export function memberTitle(id){return ({azhe:'巡视管理员',lin:'高三语文课代表',wuji:'潜水会员',jie:'高三住校生',yida:'高三（3）班',by:'高三住校生',chen:'正式会员'})[id]||'注册会员';}
const memberLevel=id=>({azhe:8,lin:6,wuji:2,jie:5,yida:4,by:4,chen:4})[id]||3;
export function classicAuthor({id,name,people,avatar,esc}){const known=Object.hasOwn(people,id),level=memberLevel(id);return `<aside class="bbs-author"><div class="bbs-username">${known?`<a href="#profile/${id}">${esc(name)}</a>`:esc(name)}</div>${known?`<a class="bbs-avatar-link" href="#profile/${id}">${avatar(id)}</a>`:avatar(name)}<span class="bbs-member-title ${id==='azhe'?'is-moderator':''}">${memberTitle(id)}</span><span class="bbs-level" aria-label="会员等级${level}"><i style="--member-level:${level}"></i><small>LV.${level}</small></span><dl><div><dt>用户组</dt><dd>${id==='azhe'?'论坛管理组':'高三年级'}</dd></div><div><dt>状态</dt><dd>离线</dd></div></dl>${known?`<a class="bbs-profile-link" href="#profile/${id}">查看资料</a>`:'<span class="bbs-profile-link">普通会员</span>'}</aside>`;}
export function classicThread(p,{people,avatar,esc,read,finished}){return `<article class="thread-card classic-thread ${p.featured?'featured':''}"><div class="bbs-thread-icon" aria-hidden="true">${p.id==='notice'?'▣':p.featured?'▤':'▱'}</div><div class="topic-content"><div class="thread-topline">${p.id==='notice'?'<span class="classic-tag announcement">公告</span><span class="classic-tag pinned">置顶</span>':`<span class="bbs-topic-category">[${esc(p.tag)}]</span>`}${p.featured?'<span class="classic-tag digest">精华</span>':''}<a class="thread-title" href="#post/${p.id}">${esc(p.title)}</a>${read.includes('post:'+p.id)?'<span class="read-check">已读</span>':''}</div><p>${esc(p.summary)}</p></div><div class="bbs-thread-author"><a href="#profile/${p.author}">${esc(people[p.author].handle)}</a><small>${p.time}</small></div><div class="topic-stats"><strong>${p.comments.length+(p.id==='reports'&&finished?1:0)}</strong><span>回复</span><small>${p.views} 浏览</small></div></article>`;}
export function classicPost({post:p,replies,people,avatar,esc,clueButton,actions}){
 const main=`<article class="bbs-floor bbs-original" id="floor-0">${classicAuthor({id:p.author,name:people[p.author].handle,people,avatar,esc})}<div class="bbs-floor-content"><header class="bbs-floor-header"><span>发表于 ${esc(p.time)}${p.origin?' · '+esc(p.origin):''}</span><a href="#post/${p.id}" aria-label="楼主">楼主</a></header><div class="article-content">${p.body}</div>${p.clue?`<div class="article-toolbar">${clueButton(p.clue,'＋ 把这篇帖子记下来')}<a href="#notes">查看笔记</a></div>`:''}<div class="post-signature">${esc(people[p.author].bio)}</div>${actions(p.id+':0')}</div></article>`;
 const floors=replies.map((r,i)=>{const withdrawn=r.text.includes('[作者已撤回');return `<article class="bbs-floor ${r.suspect?'suspect-reply':''}" id="floor-${i+1}">${classicAuthor({id:r.person||'',name:r.name,people,avatar,esc})}<div class="bbs-floor-content"><header class="bbs-floor-header"><span>发表于 ${esc(r.time)}</span><span>${i+1} 楼${r.badge?' · '+esc(r.badge):''}</span></header><div class="bbs-reply-text ${withdrawn?'withdrawn-message':''}"><p>${r.text}</p>${withdrawn?'<small class="withdrawal-label">（该发言已由原作者撤回）</small>':''}</div>${r.clue?clueButton(r.clue,'＋ 记下这条回复'):''}${actions(p.id+':'+(i+1))}</div></article>`;}).join('');
 return `<div class="bbs-breadcrumb"><a href="#forum">青禾论坛</a> » ${esc(p.tag)} » 帖子阅读</div><div class="bbs-thread-toolbar"><a class="bbs-reply-disabled" href="#chat/azhe">联系楼主 / 查看私信</a><span>阅读：${p.views}　|　回复：${replies.length}　|　<a href="#forum">返回版块</a></span></div><div class="bbs-thread-title"><span class="bbs-view-counter">查看：${p.views}<br>回复：${replies.length}</span><div>${p.featured?'<span class="classic-tag digest">精华</span>':''}<h1>${esc(p.title)}</h1><small>青禾校园生活 / 只看现有存档 · 按时间正序</small></div></div>${main}<div class="bbs-replies-heading">全部回复 <small>（${replies.length}）</small><span>楼层存档</span></div>${floors}<div class="bbs-bottom-pager"><span class="bbs-page-current">1</span><span>共 1 页</span><a href="#forum">« 返回版块</a></div><div class="notebook-actions">${p.id==='reports'?'<a href="#chat/azhe" class="primary">问问阿哲第三张图是谁的</a><button class="secondary" data-notes-toggle>翻开线索本</button>':'<a href="#forum" class="secondary">返回帖子列表</a>'}</div>`;
}
